-- Percepat view list_sppd (dipakai detail/review SPPD, list SPPD Saya, Persetujuan, Perlu Diproses).
-- Sebelumnya hitungan_biaya dirujuk 4x dan realisasi_biaya 2x lewat subquery berkorelasi;
-- view tsb tidak bisa di-merge sehingga tiap rujukan menghitung ulang SELURUH tabel (~0.5s/rujukan).
-- Sekarang masing-masing dihitung sekali lewat LATERAL join, mulai/selesai_tugas langsung dari tujuan_sppds.
-- Hasil sudah diverifikasi identik dengan view lama (1063 baris, 0 berbeda).
-- Rollback: db/list_sppd_view_rollback.sql

CREATE INDEX `idx_tujuan_sppds_id_sppd` ON `tujuan_sppds` (`id_sppd`);

CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `list_sppd` AS
select `a`.`id` AS `id`,`a`.`nomor_sppd` AS `nomor_sppd`,`a`.`narasi_st` AS `narasi_st`,`a`.`nomor_dokumen` AS `nomor_dokumen`,`a`.`employe_id` AS `employe_id`,`a`.`nama` AS `nama`,`a`.`jabatan` AS `jabatan`,`a`.`submitted_by` AS `submitted_by`,`b`.`first_name` AS `first_name`,`a`.`golongan_rate` AS `golongan_rate`,`c`.`golongan` AS `golongan`,`c`.`id_pihak` AS `id_pihak`,`d`.`pihak_name` AS `pihak_name`,`a`.`ketetapan` AS `ketetapan`,`e`.`dasar_ketetapan` AS `dasar_ketetapan`,`a`.`created_at` AS `created_at`,`a`.`updated_at` AS `updated_at`,if(((select `ptpemaco_esign`.`verif_steps`.`status` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`type` = 'sign')) limit 1) = 'approve'),'signed',if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` = 'rejected'))) > 0),'rejected','under_review')) AS `current_status`,if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`type` = 'check_document'))) > 0),if(((select `ptpemaco_esign`.`verif_steps`.`status` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`type` = 'verif_realisasi')) limit 1) = 'approve'),'verified',if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` = 'rejected'))) > 0),'rejected','under_review')),NULL) AS `realisasi_status`,if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` = 'rejected'))) > 0),NULL,(select `ptpemaco_esign`.`verif_steps`.`id_employe` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` is null)) order by `ptpemaco_esign`.`verif_steps`.`step` limit 1)) AS `current_reviewer`,(select `ptpemaco_esign`.`verif_steps`.`type` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` is null) and (`ptpemaco_esign`.`verif_steps`.`id_employe` = if(((select count(`ptpemaco_esign`.`verif_steps`.`id_employe`) from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` = 'rejected'))) > 0),NULL,(select `ptpemaco_esign`.`verif_steps`.`id_employe` from `ptpemaco_esign`.`verif_steps` where ((`ptpemaco_esign`.`verif_steps`.`id_doc` = `a`.`nomor_dokumen`) and (`ptpemaco_esign`.`verif_steps`.`status` is null)) order by `ptpemaco_esign`.`verif_steps`.`step` limit 1)))) limit 1) AS `current_type`,`hb`.`perkiraan_total` AS `perkiraan_total`,`hb`.`uang_muka` AS `uang_muka`,`rb`.`rill_biaya` AS `rill_biaya`,`rb`.`rill_tiket` AS `rill_tiket`,if(((select `proses`.`id` from `proses` where ((`proses`.`id_sppd` = `a`.`id`) and (`proses`.`as` = 'umum')) limit 1) is null),0,1) AS `by_umum`,if(((select `proses`.`id` from `proses` where ((`proses`.`id_sppd` = `a`.`id`) and (`proses`.`as` = 'uangmuka')) limit 1) is null),0,1) AS `uangmuka`,if(((select `proses`.`id` from `proses` where ((`proses`.`id_sppd` = `a`.`id`) and (`proses`.`as` = 'keuangan')) limit 1) is null),0,1) AS `by_keuangan`,(select `ts`.`waktu_berangkat` from `tujuan_sppds` `ts` where (`ts`.`id_sppd` = `a`.`id`) order by `ts`.`waktu_berangkat` limit 1) AS `mulai_tugas`,(select `ts`.`waktu_kembali` from `tujuan_sppds` `ts` where (`ts`.`id_sppd` = `a`.`id`) order by `ts`.`waktu_berangkat` desc limit 1) AS `selesai_tugas` from ((((`sppds` `a` join `ptpemaco_apam`.`employees` `b`) join `golongan_sppds` `c`) join `pihaks` `d`) join `ketetapan_sppds` `e`) left join lateral (select sum(`total_biaya`) AS `perkiraan_total`, sum(`uang_muka`) AS `uang_muka` from `hitungan_biaya` where `hitungan_biaya`.`id_sppd` = `a`.`id`) `hb` on true left join lateral (select sum(`jumlah_rill`) AS `rill_biaya`, sum(`rill_tiket`) AS `rill_tiket` from `realisasi_biaya` where `realisasi_biaya`.`id_sppd` = `a`.`id`) `rb` on true where ((`a`.`submitted_by` = `b`.`employe_id`) and (`a`.`golongan_rate` = `c`.`id`) and (`c`.`id_pihak` = `d`.`id`) and (`a`.`ketetapan` = `e`.`id`));
